"""Minimal PDF text extractor: inflate FlateDecode streams, pull strings from
Tj / TJ / ' / " operators, and insert spaces for large negative kerns.
Standard library only. Usage: python3 pdftext.py in.pdf out.txt"""
import re, sys, zlib

def unescape(s):
    out, i = [], 0
    while i < len(s):
        c = s[i]
        if c == 0x5C and i + 1 < len(s):  # backslash
            n = s[i + 1]
            m = {0x6E: 10, 0x72: 13, 0x74: 9, 0x62: 8, 0x66: 12, 0x28: 40, 0x29: 41, 0x5C: 92}
            if n in m:
                out.append(m[n]); i += 2; continue
            if 0x30 <= n <= 0x37:
                j = i + 1; v = 0; k = 0
                while j < len(s) and k < 3 and 0x30 <= s[j] <= 0x37:
                    v = v * 8 + (s[j] - 0x30); j += 1; k += 1
                out.append(v & 0xFF); i = j; continue
            i += 2; continue
        out.append(c); i += 1
    return bytes(out)

def strings_in(arr):
    parts, i = [], 0
    while i < len(arr):
        c = arr[i]
        if c == 0x28:  # (
            depth, j = 1, i + 1
            while j < len(arr) and depth:
                if arr[j] == 0x5C: j += 2; continue
                if arr[j] == 0x28: depth += 1
                elif arr[j] == 0x29: depth -= 1
                j += 1
            parts.append(unescape(arr[i + 1:j - 1]).decode('latin-1')); i = j
        else:
            m = re.match(rb'-?\d+\.?\d*', arr[i:])
            if m:
                if float(m.group()) < -180: parts.append(' ')
                i += len(m.group())
            else:
                i += 1
    return ''.join(parts)

data = open(sys.argv[1], 'rb').read()
texts = []
for m in re.finditer(rb'stream\r?\n', data):
    start = m.end()
    end = data.find(b'endstream', start)
    raw = data[start:end]
    try:
        dec = zlib.decompress(raw)
    except Exception:
        try:
            dec = zlib.decompressobj().decompress(raw)
        except Exception:
            continue
    if b'BT' not in dec:
        continue
    page = []
    for bt in re.finditer(rb'BT(.*?)ET', dec, re.S):
        blk = bt.group(1)
        line = []
        for op in re.finditer(rb'(\[(?:[^\]\\]|\\.)*\])\s*TJ|(\((?:[^)\\]|\\.)*\))\s*(?:Tj|\'|")|(T\*|Td|TD|Tm)', blk, re.S):
            if op.group(1):
                line.append(strings_in(op.group(1)[1:-1]))
            elif op.group(2):
                line.append(strings_in(op.group(2)))
            else:
                line.append('\n')
        page.append(''.join(line))
    texts.append('\n'.join(page))
open(sys.argv[2], 'w').write('\n\n=====STREAM=====\n\n'.join(texts))
print(len(texts), 'text streams')

