"""PDF text extractor with per-font decoding (ToUnicode CMaps, else /Differences
glyph names). Standard library only. Usage: python3 pdftext2.py in.pdf out.txt"""
import re, sys, zlib

GLYPH = {'space':' ','period':'.','comma':',','colon':':','semicolon':';','hyphen':'-','endash':'-','emdash':'-',
 'parenleft':'(','parenright':')','bracketleft':'[','bracketright':']','braceleft':'{','braceright':'}',
 'equal':'=','plus':'+','minus':'-','slash':'/','less':'<','greater':'>','exclam':'!','question':'?',
 'quoteright':"'",'quoteleft':"'",'quotedblleft':'"','quotedblright':'"','asterisk':'*','percent':'%',
 'zero':'0','one':'1','two':'2','three':'3','four':'4','five':'5','six':'6','seven':'7','eight':'8','nine':'9',
 'fi':'fi','fl':'fl','ff':'ff','ffi':'ffi','ffl':'ffl','bar':'|','underscore':'_','numbersign':'#',
 'ampersand':'&','dollar':'$','at':'@','quotesingle':"'",'grave':'`','asciicircum':'^','asciitilde':'~',
 'backslash':'\\','radical':'sqrt','summation':'SUM','multiply':'x','periodcentered':'.','bullet':'*',
 'lessequal':'<=','greaterequal':'>=','approxequal':'~=','similar':'~','element':'in','infinity':'inf',
 'alpha':'alpha','beta':'beta','gamma':'gamma','delta':'delta','epsilon':'eps','lambda':'lambda','pi':'pi',
 'mu':'mu','sigma':'sigma','theta':'theta','Omega':'Omega','ellipsis':'...','dieresis':'"','acute':"'",
 'lessmuch':'<<','greatermuch':'>>','dotaccent':'.','prime':"'",'arrowright':'->','negationslash':'/'}

data = open(sys.argv[1], 'rb').read()
objs = {}
for m in re.finditer(rb'(\d+)\s+0\s+obj(.*?)endobj', data, re.S):
    objs[int(m.group(1))] = m.group(2)

def stream_of(body):
    m = re.search(rb'stream\r?\n', body)
    if not m: return None
    raw = body[m.end():]
    e = raw.rfind(b'endstream')
    raw = raw[:e] if e >= 0 else raw
    try: return zlib.decompress(raw)
    except Exception:
        try: return zlib.decompressobj().decompress(raw)
        except Exception: return None

def ref(body, key):
    m = re.search(rb'/' + key + rb'\s+(\d+)\s+0\s+R', body)
    return int(m.group(1)) if m else None

def cmap_of(n):
    s = stream_of(objs.get(n, b'')) or b''
    mp = {}
    for blk in re.findall(rb'beginbfchar(.*?)endbfchar', s, re.S):
        for a, b in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            try: mp[int(a, 16)] = bytes.fromhex(b.decode()).decode('utf-16-be')
            except Exception: pass
    for blk in re.findall(rb'beginbfrange(.*?)endbfrange', s, re.S):
        for a, b, c in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            lo, hi, st = int(a, 16), int(b, 16), int(c, 16)
            for k in range(lo, hi + 1):
                try: mp[k] = chr(st + k - lo)
                except Exception: pass
    return mp

def diff_of(body):
    enc = body
    r = ref(body, rb'Encoding')
    if r is not None: enc = objs.get(r, b'')
    m = re.search(rb'/Differences\s*\[(.*?)\]', enc, re.S)
    mp = {}
    if not m: return mp
    code = 0
    for tok in re.findall(rb'\d+|/[^\s/\[\]]+', m.group(1)):
        if tok[:1] == b'/':
            name = tok[1:].decode('latin-1')
            ch = GLYPH.get(name, name if len(name) == 1 else '<%s>' % name)
            mp[code] = ch; code += 1
        else:
            code = int(tok)
    return mp

fontmap = {}
def font_decoder(n):
    if n in fontmap: return fontmap[n]
    body = objs.get(n, b'')
    mp = {}
    tu = ref(body, rb'ToUnicode')
    if tu is not None: mp = cmap_of(tu)
    if not mp: mp = diff_of(body)
    fontmap[n] = mp
    return mp

def unescape(s):
    out, i = [], 0
    while i < len(s):
        c = s[i]
        if c == 0x5C and i + 1 < len(s):
            n = s[i + 1]
            mm = {0x6E: 10, 0x72: 13, 0x74: 9, 0x62: 8, 0x66: 12, 0x28: 40, 0x29: 41, 0x5C: 92}
            if n in mm: out.append(mm[n]); i += 2; continue
            if 0x30 <= n <= 0x37:
                j = i + 1; v = 0; k = 0
                while j < len(s) and k < 3 and 0x30 <= s[j] <= 0x37:
                    v = v * 8 + (s[j] - 0x30); j += 1; k += 1
                out.append(v & 0xFF); i = j; continue
            if n in (10, 13): i += 2; continue
            out.append(n); i += 2; continue
        out.append(c); i += 1
    return bytes(out)

def resolve_dict(body, key):
    m = re.search(rb'/' + key + rb'\s*<<(.*?)>>', body, re.S)
    if m: return m.group(1)
    r = ref(body, key)
    return objs.get(r, b'') if r is not None else b''

pages = [n for n, b in objs.items() if re.search(rb'/Type\s*/Page\b', b)]
out = []
for pn in sorted(pages):
    body = objs[pn]
    res = resolve_dict(body, rb'Resources')
    fonts = dict((k, int(v)) for k, v in re.findall(rb'/([A-Za-z0-9_.+-]+)\s+(\d+)\s+0\s+R', resolve_dict(res, rb'Font')))
    cont = re.search(rb'/Contents\s*(\[[^\]]*\]|\d+\s+0\s+R)', body)
    if not cont: continue
    refs = [int(x) for x in re.findall(rb'(\d+)\s+0\s+R', cont.group(1))]
    stream = b''.join((stream_of(objs.get(r, b'')) or b'') for r in refs)
    cur = {}
    text = []
    for tok in re.finditer(rb'/([A-Za-z0-9_.+-]+)\s+[-\d.]+\s+Tf|(\[(?:[^\]\\]|\\.)*\])\s*TJ|(\((?:[^)\\]|\\.)*\))\s*(?:Tj|\'|")|(T\*|Td|TD)', stream, re.S):
        if tok.group(1):
            cur = font_decoder(fonts.get(tok.group(1), -1))
        elif tok.group(2) or tok.group(3):
            arr = tok.group(2)[1:-1] if tok.group(2) else tok.group(3)
            i = 0
            while i < len(arr):
                if arr[i] == 0x28:
                    depth, j = 1, i + 1
                    while j < len(arr) and depth:
                        if arr[j] == 0x5C: j += 2; continue
                        if arr[j] == 0x28: depth += 1
                        elif arr[j] == 0x29: depth -= 1
                        j += 1
                    for b in unescape(arr[i + 1:j - 1]):
                        text.append(cur.get(b, chr(b) if 32 <= b < 127 else ''))
                    i = j
                else:
                    mm = re.match(rb'-?\d+\.?\d*', arr[i:])
                    if mm:
                        if float(mm.group()) < -180: text.append(' ')
                        i += len(mm.group())
                    else: i += 1
        else:
            text.append('\n')
    out.append(''.join(text))
open(sys.argv[2], 'w').write('\n\n=====PAGE=====\n\n'.join(out))
print(len(out), 'pages')
